this.isLoading = true;
this.hasError = false;
try {
  const items = await this.countriesApi.query.countries({ filter: { continent: { eq: 'AS' } } }, { code: true, name: true, native: true, capital: true, emoji: true });
  this.countries = items;
} catch (err) {
  this.hasError = true;
} finally {
  this.isLoading = false;
}
